// Pull Subject + a plain-text body out of the raw Gmail message payload.
// Gmail base64url-encodes part bodies (- and _ instead of + and /, no
// padding); walk payload.parts recursively since multipart messages nest.
function header(payload, name) {
  const h = (payload.headers || []).find(
    (x) => x.name.toLowerCase() === name.toLowerCase()
  );
  return h ? h.value : '';
}
function findPart(payload, mimeType) {
  if (!payload) return null;
  if (payload.mimeType === mimeType && payload.body && payload.body.data) {
    return payload.body.data;
  }
  if (payload.parts) {
    for (const p of payload.parts) {
      const found = findPart(p, mimeType);
      if (found) return found;
    }
  }
  return null;
}
function decode(data) {
  return Buffer.from(data.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf-8');
}
function stripHtml(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

const payload = $json.payload || {};
const subject = header(payload, 'Subject');
let body = '';
const plain = findPart(payload, 'text/plain');
if (plain) {
  body = decode(plain);
} else {
  const html = findPart(payload, 'text/html');
  if (html) body = stripHtml(decode(html));
}
return { json: { id: $json.id, subject, body: body.slice(0, 3000) } };
